    def project(p):
        """Project a proposed point Euclideanly onto the reference simplex."""
        p = np.maximum(np.asarray(p, dtype=float), 0.0)
        total = p.sum()
        if total <= 1.0:
            return p
        shift = 0.5 * (total - 1.0)
        p -= shift
        if p[0] < 0.0:
            return np.array((0.0, 1.0))
        if p[1] < 0.0:
            return np.array((1.0, 0.0))
        return p
